package com.pizzalab.service;
import com.pizzalab.dto.*; import com.pizzalab.exception.ConflictException; import com.pizzalab.model.*; import com.pizzalab.repository.*; import org.junit.jupiter.api.Test; import java.time.Instant; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
/** Pruebas unitarias de reglas: no necesitan HTTP ni SQLite. */
class OrderServiceTest {
 @Test void calculaElPrecioDelServidorYNoDelCliente(){OrderRepository orders=mock(OrderRepository.class);PizzaRepository pizzas=mock(PizzaRepository.class);when(pizzas.findById(1)).thenReturn(Optional.of(new Pizza(1,"Margarita","x",1200)));when(orders.insert(any(),anyInt(),any())).thenReturn(7L);Order stored=new Order(7,OrderStatus.RECIBIDO,2400,Instant.now(),List.of(new OrderLine(1,"Margarita",1200,2)));when(orders.findById(7)).thenReturn(Optional.of(stored));OrderService service=new OrderService(orders,pizzas,new NoPromotionStrategy(),List.of());OrderResponse result=service.create(new CreateOrderRequest(List.of(new OrderItemRequest(1,2))));assertEquals(2400,result.totalCents());verify(orders).insert(eq(OrderStatus.RECIBIDO),eq(2400),any());}
 @Test void rechazaSaltarseEstados(){OrderRepository orders=mock(OrderRepository.class);Order current=new Order(1,OrderStatus.RECIBIDO,100,Instant.now(),List.of());when(orders.findById(1)).thenReturn(Optional.of(current));OrderService service=new OrderService(orders,mock(PizzaRepository.class),new NoPromotionStrategy(),List.of());assertThrows(ConflictException.class,()->service.changeStatus(1,OrderStatus.LISTO));verify(orders,never()).updateStatus(anyLong(),any());}
}
